const now = new Date();
const endDate = new Date(now);
endDate.setDate(endDate.getDate() - 1);
const startDate = new Date(now);
startDate.setDate(startDate.getDate() - 90);
const fmt = d => d.toISOString().split('T')[0];
return [{ json: { gsc_query_json: JSON.stringify({ startDate: fmt(startDate), endDate: fmt(endDate), dimensions: ['query'], rowLimit: 2500, dataState: 'final' }) } }];

const gscData = $('GSC Query').item.json;
const serpData = $('SerpAPI').item.json;
const blogResp = $('Leer Blog Sheet').first().json;
const blogVals = (blogResp.values || []).slice(1);
const existingKeywords = blogVals.map(row => (row[0] || '').toLowerCase().trim()).filter(k => k);

const redesResp = {};
const redesVals = (redesResp.values || []).slice(1);
const existingSituations = redesVals.filter(row => (row[0]||'').trim() === 'Entretenimiento').map(row => (row[1] || '').toLowerCase().trim()).filter(s => s);

const gscQueries = (gscData.rows||[]).filter(r=>(r.impressions||0)>=3).sort((a,b)=>(b.impressions||0)-(a.impressions||0)).map(r=>'"'+r.keys[0]+'" (pos:'+(r.position||0).toFixed(1)+', imp:'+r.impressions+')').slice(0,60).join('\n');
const paa = (serpData.related_questions||[]).map(q=>q.question).join('\n');
const related = (serpData.related_searches||[]).map(s=>s.query).join('\n');

const systemMsg = 'Eres especialista en SEO y contenido editorial para Bigotes Felinos, blog de referencia sobre gatos para hispanohablantes. Generas ideas con demanda real y potencial de posicionamiento en Google.';

const userMsg = 'Genera ideas de contenido para BLOG y ENTRETENIMIENTO.\n\n' +
  'KEYWORDS YA EN EL BLOG (NO repetir — verificar similitud ≥50% palabras):' + '\n' + (existingKeywords.slice(0,150).join('\n')||'(Sin datos)') +
  '\n\nSITUACIONES ENTRETENIMIENTO YA USADAS (NO repetir):' + '\n' + (existingSituations.slice(0,30).join('\n')||'(Ninguna)') +
  '\n\nQUERIES REALES GSC (últimos 90 días, ≥3 impresiones):' + '\n' + (gscQueries||'(Sin datos de GSC)') +
  '\n\nGENTE TAMBIÉN PREGUNTA (PAA):' + '\n' + (paa||'(Sin datos)') +
  '\n\nBÚSQUEDAS RELACIONADAS:' + '\n' + (related||'(Sin datos)') +
  '\n\nINSTRUCCIONES BLOG (15 ideas):' +
  '\n- Prioriza queries reales de GSC/PAA con oportunidad real' +
  '\n- Descarta cualquier keyword con ≥50% palabras significativas iguales a alguna existente' +
  '\n- Intención informacional o comercial, dueños de gatos hispanohablantes' +
  '\n- COLOMBIA-FIRST QUOTA: MÍNIMO 6 de las 15 ideas DEBEN tener modificador colombiano explícito (Colombia, Bogotá, Medellín, Cali, Barranquilla, Cartagena, COP, pesos colombianos). Razón estratégica: en queries colombianos los competidores AIO son marketplaces/aseguradoras (Mercado Libre, Compensar, SURA), NO blogs felinos — ahí Bigotes Felinos gana rápido' +
  '\n- Ejemplos de keywords colombianas valiosas: "cuánto cuesta esterilizar un gato en Bogotá", "mejores razas de gato para apartamento Colombia", "veterinario domicilio gatos Medellín precio", "dónde adoptar gato Bogotá", "hospedaje para gatos Cali", "vacunas obligatorias gato Colombia precio", "alimento Royal Canin gato Colombia precio"' +
  '\n- HIPER-LOCAL QUOTA: De las 6 colombianas, MÍNIMO 4 deben ser HIPER-LOCALES con CIUDAD + BARRIO/ZONA específicos. Volumen individual bajo (10-50 búsquedas/mes) pero competencia casi nula y conversión 5-15x mayor que kw nacionales. Zonas válidas: Bogotá (Chapinero, Usaquén, Norte, Chapinero, Suba, Engativá, Chía), Medellín (El Poblado, Laureles, Envigado, Sabaneta, Itagüí), Cali (Norte, Sur, Pance, San Fernando), Barranquilla (Norte, Centro, Soledad)' +
  '\n- Ejemplos hiper-locales: "veterinario 24h Chapinero Bogotá", "esterilización gato Cali Sur precio", "tienda de mascotas El Poblado Medellín", "guardería para gatos Usaquén", "vacuna triple felina Bogotá Norte", "antiparasitarios gatos Laureles Medellín", "cremación gato Envigado", "adopción gatos Suba Bogotá"' +
  '\n- Las otras 9 ideas restantes pueden ser hispanohablantes generales (México, España, Argentina) o sin modificador geográfico' +
  '\n- Incluir modificadores de país cuando aplique (Colombia, México, etc.)' +
  '\n- Prioridad ALTA: queries GSC con posición 11-30 + queries colombianas' +
  '\n\nINSTRUCCIONES ENTRETENIMIENTO (5 ideas):' +
  '\n- Comportamiento felino REAL y verificable' +
  '\n- Humor por reconocimiento exacto ("esto es literalmente mi gato")' +
  '\n- NO repetir situaciones ya usadas' +
  '\n\nRESPUESTA JSON ESTRICTO:' +
  '{"blog_ideas":[{"keyword":"...","nicho":"Salud|Alimentación|Comportamiento|Razas|Cuidados","pais":"Colombia|México|España|General","audiencia":"...","intencion":"Informacional|Comercial|Transaccional","prioridad":"Alta|Media|Baja","fuente":"GSC|PAA|Relacionadas|GPT"}]}';

const body = {model:'gpt-4o',response_format:{type:'json_object'},max_tokens:4000,messages:[{role:'system',content:systemMsg},{role:'user',content:userMsg}]};
return [{json:{gpt_body_json:JSON.stringify(body),existingKeywords,existingSituations}}];

const raw = $input.item.json.choices?.[0]?.message?.content || '';
const prev = $('Construir Prompt GPT').item.json;
const existingKeywords = prev.existingKeywords || [];
const existingSituations = prev.existingSituations || [];

let ideas;
try { ideas = JSON.parse(raw); } catch(e) { throw new Error('Ideas parse error: ' + raw.substring(0,300)); }

function jaccard(a, b) {
  const stop = new Set(['de','la','el','en','y','para','un','una','con','del','los','las','que','gato','gatos','mi','su','es','se','al','como','si','lo','le']);
  const w = s => new Set(s.toLowerCase().split(/\s+/).filter(t=>t.length>2&&!stop.has(t)));
  const wa=w(a), wb=w(b);
  if(!wa.size||!wb.size) return 0;
  const inter=[...wa].filter(t=>wb.has(t)).length;
  return inter/new Set([...wa,...wb]).size;
}

// Mapeo nicho → hub + cluster_parent (Sprint 3)
const HUB_MAP = {
  'Salud': { hub: 'Salud', slug: 'guia-salud-felina' },
  'Alimentación': { hub: 'Alimentación', slug: 'guia-alimentacion-gatos' },
  'Alimentacion': { hub: 'Alimentación', slug: 'guia-alimentacion-gatos' },
  'Razas': { hub: 'Razas', slug: 'guia-razas-gatos' },
  'Comportamiento': { hub: 'Mundo', slug: 'guia-comportamiento-felino' },
  'Cuidados': { hub: 'Mundo', slug: 'guia-comportamiento-felino' },
  'Entretenimiento': { hub: 'Mundo', slug: 'guia-comportamiento-felino' },
  'Mundo': { hub: 'Mundo', slug: 'guia-comportamiento-felino' }
};
function mapHub(nicho) {
  const k = (nicho||'').trim();
  return HUB_MAP[k] || HUB_MAP['Mundo']; // fallback a Mundo si nicho no reconocido
}

const rawBlog = ideas.blog_ideas || [];
const rawEnt = ideas.ent_ideas || [];

// Pasada 1: dedup contra existentes en el Sheet
const filteredBlog = rawBlog.filter(idea => {
  const kw = (idea.keyword||'').toLowerCase().trim();
  return kw && !existingKeywords.some(ex=>jaccard(kw,ex)>=0.5);
});

const filteredEnt = rawEnt.filter(situation => {
  const s = (situation||'').toLowerCase().trim();
  return s && !existingSituations.some(ex=>jaccard(s,ex)>=0.5);
});

// Pasada 2: dedup ENTRE las ideas nuevas (evita duplicados internos de GPT en el mismo run)
const dedupedBlog = [];
for (const idea of filteredBlog) {
  const kw = (idea.keyword||'').toLowerCase().trim();
  const isDup = dedupedBlog.some(d => jaccard(kw, (d.keyword||'').toLowerCase().trim()) >= 0.5);
  if (!isDup) dedupedBlog.push(idea);
}

const dedupedEnt = [];
for (const situation of filteredEnt) {
  const s = (situation||'').toLowerCase().trim();
  const isDup = dedupedEnt.some(d => jaccard(s, (d||'').toLowerCase().trim()) >= 0.5);
  if (!isDup) dedupedEnt.push(situation);
}

// blogValues: 19 columnas (A-S) — incluye hub (R) y cluster_parent (S) auto-asignados desde nicho
const blogValues = dedupedBlog.map(idea => {
  const hubInfo = mapHub(idea.nicho);
  return [
    idea.keyword||'',
    'Pendiente',
    idea.prioridad||'Media',
    idea.nicho||'',
    idea.pais||'General',
    idea.audiencia||'',
    idea.intencion||'Informacional',
    '', '', '', '', '', '', // H-M: url_post, wordcount, posicion_gsc, fecha_objetivo, fecha_social, fecha_reoptimizado
    '', '', '', '',          // N-Q: copies huérfanos vacíos
    hubInfo.hub,             // R: hub
    hubInfo.slug             // S: cluster_parent
  ];
});

const entValues = dedupedEnt.map(s => ['Entretenimiento',s,'','','Idea','','','','']);

const blog_ideas_json = JSON.stringify({values:blogValues});
const ent_ideas_json = JSON.stringify({values:entValues});

const blogVsSheet = rawBlog.length - filteredBlog.length;
const blogInternal = filteredBlog.length - dedupedBlog.length;
const entVsSheet = rawEnt.length - filteredEnt.length;
const entInternal = filteredEnt.length - dedupedEnt.length;

// Resumen por hub para Telegram
const hubCounts = {};
for (const idea of dedupedBlog) {
  const h = mapHub(idea.nicho).hub;
  hubCounts[h] = (hubCounts[h] || 0) + 1;
}
const hubBreakdown = Object.entries(hubCounts).map(([h,c]) => '  • ' + h + ': ' + c).join('\n');

const summary = '\u{1F4A1} *Ideas generadas* ✅\n\n\u{1F4DD} *Blog:* '+dedupedBlog.length+' nuevas\n  • ' + blogVsSheet + ' descartadas vs Sheet\n  • ' + blogInternal + ' duplicados internos de GPT\n\n*Por hub:*\n' + hubBreakdown + '\n\n\u{1F3AD} *Entretenimiento:* '+dedupedEnt.length+' nuevas\n  • ' + entVsSheet + ' descartadas vs Sheet\n  • ' + entInternal + ' duplicados internos de GPT\n\n_Añadidas en Google Sheets con hub/cluster_parent auto-asignados._';

return [{json:{blog_ideas_json,ent_ideas_json,blog_count:dedupedBlog.length,ent_count:dedupedEnt.length,summary}}];
